import XCTest
@testable import MirNavigation

final class CapturedCombatTests: XCTestCase {
    func testLiveServerCombatAndLootFrames() throws {
        let captures = [
            "546d5b576f62686b4a6551436466686b6464686b6464686b6464686b6464686b6464686b643f",
            "6464686b645f6b696464686b6464686b6964746b6468686a686474676465686b6564746b5f64686b64644b2f6464686b6464686b6464686b6464686b6464686b6464686b64644b2f6466686b666868626467686b656468676464686b6464686b64644b",
            "515f515a645c686b496551436467686b6a64736b6464686b64644b",
            "515f515a646668694b6556476467686b6a64736b6464686b64644b",
            "515f515a64666868496550436467686b",
            "546d5b576f6b68685f64456b6466686b6464686b6464686b6464595b5f5168656464686b643f",
            "546d5b576f61686a5f64716b645d686a",
            "6862446a5f6668614b65523f6466686b6464686b6464686b64644b5d736c7778783f5c6261556a",
            "",
            "515f515a645e686b496550436467686b6a64736b6464686b64644b",
            "4155595f5e6e6a6b49655043646a686854424d443f3f",
            "",
            "4155595f5e6f6a6b496550436464686b",
            "6065686764456a683f64685f6464686b"
        ]
        var ids:Set<UInt16>=[]
        for hex in captures {
            let chars=Array(hex)
            let frame=stride(from:0,to:chars.count,by:2).map { UInt8(String(chars[$0...($0+1)]),radix:16)! }
            ids.insert(try MirWire.packet(frame).id)
        }
        XCTAssertTrue(Set<UInt16>([31,32,200,201,610,611,653]).isSubset(of:ids))
    }
}
